    types=collections.Counter(); ts=[]; inp=out=0; usages=0
    for line in p.open(encoding='utf-8'):
        try: o=json.loads(line)
        except: continue
        if o.get('type'): types[o['type']]+=1
        if o.get('timestamp'): ts.append(o['timestamp'])
        def walk(x):
            nonlocal_dummy=None
            global inp,out,usages
