            elif isinstance(x,list):
                for v in x: walk(v)
        walk(o)
    print(p.name, 'lines=',sum(types.values()), 'start=',min(ts) if ts else None, 'end=',max(ts) if ts else None, 'input=',inp,'output=',out,'usage_nodes=',usages)
    print(' types=',dict(types))
'@ | python -","description":"Summarize JSON sessions and tokens","initial_wait":30,"mode":"sync"}

